INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5870457, 853992, 96751, '<td valign="top">Front page stuff here.  Exquisite eyes, perfect lighting on the face and the shaw over hear shoulder.  Terrific colors.  Love, love, love it.</td>', 'Front page stuff here.  Exquisite eyes, perfect lighting on the face and the shaw over hear shoulder.  Terrific colors.  Love, love, love it.', '2010-02-17 01:51:56.000000', NULL, 1),
(5870458, 853930, 96751, '<td valign="top">Wonderful fantasy shot.  The eyes are a bit disturbing, but the set up is stellar.</td>', 'Wonderful fantasy shot.  The eyes are a bit disturbing, but the set up is stellar.', '2010-02-17 01:52:52.000000', NULL, 1),
(5870460, 853894, 96751, '<td valign="top">Nice detail, but I wish the lighting was not so much on the hand as on the hat.</td>', 'Nice detail, but I wish the lighting was not so much on the hand as on the hat.', '2010-02-17 01:53:16.000000', NULL, 1),
(5870462, 853918, 96751, '<td valign="top">That hat has seen many moons.</td>', 'That hat has seen many moons.', '2010-02-17 01:53:44.000000', NULL, 1),
(5870465, 853389, 96751, '<td valign="top">Hmmm.  The eyes are incredible.  But this shot seems more about them than about her headwear.</td>', 'Hmmm.  The eyes are incredible.  But this shot seems more about them than about her headwear.', '2010-02-17 01:55:02.000000', NULL, 1),
(5870466, 854012, 96751, '<td valign="top">Another lovely shot that includes headwear but isn''t about headwear.</td>', 'Another lovely shot that includes headwear but isn''t about headwear.', '2010-02-17 01:55:30.000000', NULL, 1),
(5870467, 854136, 96751, '<td valign="top">Breakfast at Tiffany''s...?  Great lighting.  Love the luster of the pearls.</td>', 'Breakfast at Tiffany''s...?  Great lighting.  Love the luster of the pearls.', '2010-02-17 01:55:53.000000', NULL, 1),
(5870469, 853166, 96751, '<td valign="top">What a mug!  I can tell it was REALLY cold :-)</td>', 'What a mug!  I can tell it was REALLY cold :-)', '2010-02-17 01:56:19.000000', NULL, 1),
(5870472, 853652, 96751, '<td valign="top">LOL!  Wonderful and humorous.  I did a double take.  Maybe just a little blown out in the highlights.</td>', 'LOL!  Wonderful and humorous.  I did a double take.  Maybe just a little blown out in the highlights.', '2010-02-17 01:56:52.000000', NULL, 1),
(5870474, 853961, 96751, '<td valign="top">Love the crop on this.  Great composition.  The straight line of the brim really defines this shot.  And that killer eye is the punctuation and counterpoint to the bling ring.  Very engaging.  My eye keeps jumping around, savoring the colors, shapes,expression...</td>', 'Love the crop on this.  Great composition.  The straight line of the brim really defines this shot.  And that killer eye is the punctuation and counterpoint to the bling ring.  Very engaging.  My eye keeps jumping around, savoring the colors, shapes,expression...', '2010-02-17 01:58:14.000000', NULL, 1),
(5870476, 854015, 96751, '<td valign="top">Gorgeous sepia shot.</td>', 'Gorgeous sepia shot.', '2010-02-17 01:58:56.000000', NULL, 1),
(5870477, 853436, 96751, '<td valign="top">There is something very frightening about her face...  Terrific textures with the veil, the mohair hat, the pearls, the waxy hand.  But scary...</td>', 'There is something very frightening about her face...  Terrific textures with the veil, the mohair hat, the pearls, the waxy hand.  But scary...', '2010-02-17 01:59:50.000000', NULL, 1),
(5870523, 854106, 112861, '<td valign="top">This was one of my favorites. The comp and colors or great, and I''m a sucker for Meso-American art/culture...<br/> <br/>(you got a good score)</td>', 'This was one of my favorites. The comp and colors or great, and I''m a sucker for Meso-American art/culture... (you got a good score)', '2010-02-17 02:28:59.000000', NULL, 1),
(5870526, 852981, 112861, '<td valign="top">...trying...to...see...it<br/> <br/>...almost...<br/> <br/>nope</td>', '...trying...to...see...it ...almost... nope', '2010-02-17 02:32:07.000000', NULL, 1),
(5870529, 853800, 112861, '<td valign="top">Tones seem a little on the red side to me.<br/>Other than that - looks pretty good.</td>', 'Tones seem a little on the red side to me.Other than that - looks pretty good.', '2010-02-17 02:33:48.000000', NULL, 1),
(5870533, 853476, 112861, '<td valign="top">As Ed Norton would say...<br/> <br/>hummina, hummina, hummina<br/> <br/>I like this one. (Just for the technical finesse, of course.)</td>', 'As Ed Norton would say... hummina, hummina, hummina I like this one. (Just for the technical finesse, of course.)', '2010-02-17 02:36:05.000000', NULL, 1),
(5870537, 854168, 112861, '<td valign="top">Cool... A "thug-xedo".<br/> <br/>I bet that gun is looking a lot bigger from the business end than the trigger side.</td>', 'Cool... A "thug-xedo". I bet that gun is looking a lot bigger from the business end than the trigger side.', '2010-02-17 02:38:20.000000', NULL, 1),
(5870543, 853930, 112861, '<td valign="top">I love the pastel-type soft look and the composition is good, but there''s something about her left eye that''s drawing my attention away from the overall shot.<br/> <br/>Still a good score.</td>', 'I love the pastel-type soft look and the composition is good, but there''s something about her left eye that''s drawing my attention away from the overall shot. Still a good score.', '2010-02-17 02:40:33.000000', NULL, 1),
