(5873881, 852981, 53814, '<td valign="top">Magical, clearly a medieval wizard, complete with gestures and all the required sorcererly props - including the iconic star on the hat. The spell is powerful. My favorite of this challenge.</td>', 'Magical, clearly a medieval wizard, complete with gestures and all the required sorcererly props - including the iconic star on the hat. The spell is powerful. My favorite of this challenge.', '2010-02-19 22:11:12.000000', NULL, 1),
(5873915, 854026, 53814, '<td valign="top">classic portrait, beautiful tones.</td>', 'classic portrait, beautiful tones.', '2010-02-19 23:03:47.000000', NULL, 1),
(5873935, 854019, 53814, '<td valign="top">I love how the tree ties the hat into the background, and the texture of the foliage ties the background into the face. A wonderful circular trip for the eyes, it both starts and ends with the eyes. Also, perfect use of over-processing, this wouldn''t work without it. I would like to see this cropped square, with about 1/3 off the top and 1/3 off the left. It wouldn''t score as well, but I believe it would be a stronger photo and would help to define the movement. As is, this deserves a high mark. -9</td>', 'I love how the tree ties the hat into the background, and the texture of the foliage ties the background into the face. A wonderful circular trip for the eyes, it both starts and ends with the eyes. Also, perfect use of over-processing, this wouldn''t work without it. I would like to see this cropped square, with about 1/3 off the top and 1/3 off the left. It wouldn''t score as well, but I believe it would be a stronger photo and would help to define the movement. As is, this deserves a high mark. -9', '2010-02-19 23:36:37.000000', NULL, 1),
(5873983, 854147, 17507, '<td valign="top">Great shot. Love the dark tones and the contrast.</td>', 'Great shot. Love the dark tones and the contrast.', '2010-02-20 01:31:06.000000', NULL, 1),
(5873984, 854103, 17507, '<td valign="top">I can''t help but stare at the drop coming off his nose.</td>', 'I can''t help but stare at the drop coming off his nose.', '2010-02-20 01:33:03.000000', NULL, 1),
(5873985, 852981, 17507, '<td valign="top">Cool abstract, but that hat''s pretty hard to make out.</td>', 'Cool abstract, but that hat''s pretty hard to make out.', '2010-02-20 01:34:20.000000', NULL, 1),
(5873986, 853436, 17507, '<td valign="top">Mourning in a white hat? The white fur seems a bit out of sync with your title.</td>', 'Mourning in a white hat? The white fur seems a bit out of sync with your title.', '2010-02-20 01:35:06.000000', NULL, 1),
(5874003, 853896, 17507, '<td valign="top">Check your spelling. I think you mean "Farce."</td>', 'Check your spelling. I think you mean "Farce."', '2010-02-20 02:26:31.000000', NULL, 1),
(5874004, 853906, 17507, '<td valign="top">Cool shot - a shame the figure is out of focus.</td>', 'Cool shot - a shame the figure is out of focus.', '2010-02-20 02:27:19.000000', NULL, 1),
(5874005, 853981, 1686, '<td valign="top">nicely captured</td>', 'nicely captured', '2010-02-20 02:28:20.000000', NULL, 1),
