(5874026, 854077, 106043, '<td valign="top">Wow!!!!!!!!!!!!! very artistic and a lot of people don''t know that!!!!!</td>', 'Wow!!!!!!!!!!!!! very artistic and a lot of people don''t know that!!!!!', '2010-02-20 03:47:17.000000', NULL, 1),
(5874055, 853942, 68586, '<td valign="top">Will or Chris . . . Chris or Will . . I''m sure it''s one of you two.<br/> <br/> :- )<br/> <br/>Nice crop and composition with both the hat brim and far arm forming gentle diagonals, while the head stays in the ''rule of thirds''.</td>', 'Will or Chris . . . Chris or Will . . I''m sure it''s one of you two.  :- ) Nice crop and composition with both the hat brim and far arm forming gentle diagonals, while the head stays in the ''rule of thirds''.', '2010-02-20 07:38:47.000000', NULL, 1),
(5874060, 853934, 68586, '<td valign="top">Astonishing colours and outfit - possibly from the Chinese New Year ?<br/> <br/>Good idea to desat to remove some of the background clutter, but inevitably hard to get rid of all of it and those straight lines still make the background a little ''busy''</td>', 'Astonishing colours and outfit - possibly from the Chinese New Year ? Good idea to desat to remove some of the background clutter, but inevitably hard to get rid of all of it and those straight lines still make the background a little ''busy''', '2010-02-20 08:01:36.000000', NULL, 1),
(5874062, 853781, 68586, '<td valign="top">Good concept that could possibly be explored even further with visual contrasts of maybe snow scenes and bright kiddies hats on grown-ups. Unfortunately the B&amp;W conversion lacks punch here and it looks more like someone sitting in their bedroom than trying to survive against the odds . . <br/> <br/>That said - staying in many teenagers bedrooms for more than 5 mins can seem a little like trying to survive . .<br/> <br/> :- )</td>', 'Good concept that could possibly be explored even further with visual contrasts of maybe snow scenes and bright kiddies hats on grown-ups. Unfortunately the B&W conversion lacks punch here and it looks more like someone sitting in their bedroom than trying to survive against the odds . .  That said - staying in many teenagers bedrooms for more than 5 mins can seem a little like trying to survive . .  :- )', '2010-02-20 08:05:36.000000', NULL, 1),
(5874063, 853821, 68586, '<td valign="top">"How do I look?" Sorta like your parents made you put a hat on for a picture . . but you weren''t really that keen  :- )<br/> <br/>Good looking lad though - I''m sure we''ll see many more pictures of him.</td>', '"How do I look?" Sorta like your parents made you put a hat on for a picture . . but you weren''t really that keen  :- ) Good looking lad though - I''m sure we''ll see many more pictures of him.', '2010-02-20 08:07:33.000000', NULL, 1),
(5874068, 853997, 68586, '<td valign="top">So if Kersten has given over her towel . .  oh never mind <br/> <br/> :- )<br/> <br/>Tastes and styles obviously vary - but to me the skin appears to be overprocessed here. This might just have worked better in B&amp;W ?</td>', 'So if Kersten has given over her towel . .  oh never mind   :- ) Tastes and styles obviously vary - but to me the skin appears to be overprocessed here. This might just have worked better in B&W ?', '2010-02-20 08:12:04.000000', NULL, 1),
(5874070, 854113, 68586, '<td valign="top">Very sweet picture and nice B&amp;W conversion.</td>', 'Very sweet picture and nice B&W conversion.', '2010-02-20 08:13:58.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5874071, 854134, 68586, '<td valign="top">Interesting concept and tremendous looking helmet - but I think there is just too much going on in the picture to distract the viewer. If you were able to get hold of this helmet and give it a little more space I think you could get a tremendous shot from it.</td>', 'Interesting concept and tremendous looking helmet - but I think there is just too much going on in the picture to distract the viewer. If you were able to get hold of this helmet and give it a little more space I think you could get a tremendous shot from it.', '2010-02-20 08:16:19.000000', NULL, 1),
(5874072, 854025, 68586, '<td valign="top">Very nice  :- )</td>', 'Very nice  :- )', '2010-02-20 08:17:11.000000', NULL, 1),
(5874073, 854008, 68586, '<td valign="top">Nice idea and wonderful blue feathers - but just a little too dark overall</td>', 'Nice idea and wonderful blue feathers - but just a little too dark overall', '2010-02-20 08:18:01.000000', NULL, 1),
(5874075, 853816, 68586, '<td valign="top">Wow - you wouldn''t want to leave that helmet sitting on a chair . .</td>', 'Wow - you wouldn''t want to leave that helmet sitting on a chair . .', '2010-02-20 08:18:33.000000', NULL, 1),
(5874191, 853918, 35021, '<td valign="top">Love the faded colors and overall look/feel - 9</td>', 'Love the faded colors and overall look/feel - 9', '2010-02-20 11:08:57.000000', NULL, 1),
(5874192, 853762, 35021, '<td valign="top">Not only creative, but excellent shot!</td>', 'Not only creative, but excellent shot!', '2010-02-20 11:09:08.000000', NULL, 1),
(5874194, 854070, 35021, '<td valign="top">Excellent tones and contrast, great work!</td>', 'Excellent tones and contrast, great work!', '2010-02-20 11:10:15.000000', NULL, 1),
(5874197, 853888, 35021, '<td valign="top">Excellent composition and lighting</td>', 'Excellent composition and lighting', '2010-02-20 11:10:48.000000', NULL, 1),
(5874200, 853476, 35021, '<td valign="top">Like the soft lighting and level of contrast, overall, excellent shot!</td>', 'Like the soft lighting and level of contrast, overall, excellent shot!', '2010-02-20 11:12:49.000000', NULL, 1),
(5874202, 854121, 35021, '<td valign="top">Very nice image!  The bat ear on the left has a bit too much lighting, is a little distracting from the focus of eyes.  Overall, great work! 8</td>', 'Very nice image!  The bat ear on the left has a bit too much lighting, is a little distracting from the focus of eyes.  Overall, great work! 8', '2010-02-20 11:14:35.000000', NULL, 1),
(5874203, 854113, 35021, '<td valign="top">I really love this photo!  I would have liked to have seen some more tones in her face... the lighting seems a bit flat.  But her eyes have excellent contrast.  8</td>', 'I really love this photo!  I would have liked to have seen some more tones in her face... the lighting seems a bit flat.  But her eyes have excellent contrast.  8', '2010-02-20 11:15:44.000000', NULL, 1),
(5874363, 854123, 12405, '<td valign="top">I would have gone another point up if the straw wasn''t there. I''m finding that rather distracting.</td>', 'I would have gone another point up if the straw wasn''t there. I''m finding that rather distracting.', '2010-02-20 13:52:29.000000', NULL, 1),
(5874486, 854028, 28427, '<td valign="top">Very beautiful contrast and great sharpness.</td>', 'Very beautiful contrast and great sharpness.', '2010-02-20 16:16:50.000000', NULL, 1),
(5874487, 853877, 28427, '<td valign="top">There''s slightly too much negative space at the base of the photograph.  Then the head could have had some more space above it.  A different crop could have done it I think, though I don''t know how your original was set.</td>', 'There''s slightly too much negative space at the base of the photograph.  Then the head could have had some more space above it.  A different crop could have done it I think, though I don''t know how your original was set.', '2010-02-20 16:18:44.000000', NULL, 1),
(5874488, 853678, 28427, '<td valign="top">Why didn''t you show her face completely? This crop doesn''t work to well for me.<br/>I''m missing some sharpness as well and there''s seems something strange going one around her eyes.</td>', 'Why didn''t you show her face completely? This crop doesn''t work to well for me.I''m missing some sharpness as well and there''s seems something strange going one around her eyes.', '2010-02-20 16:20:28.000000', NULL, 1),
(5874489, 853975, 28427, '<td valign="top">R.I.P. fellow photographer.  But at least you''ve got a special photograph :)</td>', 'R.I.P. fellow photographer.  But at least you''ve got a special photograph :)', '2010-02-20 16:21:45.000000', NULL, 1),
(5874490, 854118, 28427, '<td valign="top">I think your focusing point is on her shoulder in stead of on her head.</td>', 'I think your focusing point is on her shoulder in stead of on her head.', '2010-02-20 16:23:20.000000', NULL, 1),
(5874492, 854144, 28427, '<td valign="top">Polaroid style... one likes or one doesn''t like it.  I hope there will be enough viewers liking this style.</td>', 'Polaroid style... one likes or one doesn''t like it.  I hope there will be enough viewers liking this style.', '2010-02-20 16:24:37.000000', NULL, 1),
(5874505, 853188, 114128, '<td valign="top">She has such beautiful eyes!!! great detail and i really like the colour scheme of this picture, its very innocent and peaceful</td>', 'She has such beautiful eyes!!! great detail and i really like the colour scheme of this picture, its very innocent and peaceful', '2010-02-20 16:39:03.000000', NULL, 1),
(5874509, 852981, 28427, '<td valign="top">A small update: I''ve revisited this photograph several times. I just didn''t want to give up. Suddenly, it hit me: I finally saw the wizard hat :) There are still things to figure out.  Maybe you''ll see me stop by a few times more ;)<br/>I hope that, after the challenge, you''ll show us what we were actually looking at.  That at least we deserve for all this effort *8*</td>', 'A small update: I''ve revisited this photograph several times. I just didn''t want to give up. Suddenly, it hit me: I finally saw the wizard hat :) There are still things to figure out.  Maybe you''ll see me stop by a few times more ;)I hope that, after the challenge, you''ll show us what we were actually looking at.  That at least we deserve for all this effort *8*', '2010-02-20 17:01:11.000000', NULL, 1),
(5874514, 854029, 28427, '<td valign="top">Good concept.  Although I''m a bit divided: I see this photograph better without the interior around.  Meaning: I think that in a studio, without anything around, this would be much more standing out.  This doesn''t take away the fact that I''m curious how you did the hat-floating-thing.</td>', 'Good concept.  Although I''m a bit divided: I see this photograph better without the interior around.  Meaning: I think that in a studio, without anything around, this would be much more standing out.  This doesn''t take away the fact that I''m curious how you did the hat-floating-thing.', '2010-02-20 17:16:12.000000', NULL, 1),
(5874515, 853595, 28427, '<td valign="top">If you''re asking me: this is the winner of this challenge *10*</td>', 'If you''re asking me: this is the winner of this challenge *10*', '2010-02-20 17:17:13.000000', NULL, 1),
(5874517, 853458, 28427, '<td valign="top">She has such beautiful eyes.  She didn''t want to get rid of her pacifier :)?</td>', 'She has such beautiful eyes.  She didn''t want to get rid of her pacifier :)?', '2010-02-20 17:20:00.000000', NULL, 1),
(5874518, 853896, 28427, '<td valign="top">A farse with a bitter taste.  Not a lot of people would want to get in his role.</td>', 'A farse with a bitter taste.  Not a lot of people would want to get in his role.', '2010-02-20 17:21:05.000000', NULL, 1),
(5874523, 853338, 28427, '<td valign="top">You refer to the headwear appropriate for the job but it doesn''t show.<br/>I don''t know what other viewers will think of it.  I don''t say that it DNMC, but I would have liked seeing the headwear with it.<br/>This photograph is very well executed and for that I would give you a 7.  The fact that there''s no headwear unfortunately reduces this to *4*</td>', 'You refer to the headwear appropriate for the job but it doesn''t show.I don''t know what other viewers will think of it.  I don''t say that it DNMC, but I would have liked seeing the headwear with it.This photograph is very well executed and for that I would give you a 7.  The fact that there''s no headwear unfortunately reduces this to *4*', '2010-02-20 17:33:44.000000', NULL, 1),
(5874524, 853575, 28427, '<td valign="top">LOL - this is funny</td>', 'LOL - this is funny', '2010-02-20 17:36:59.000000', NULL, 1),
(5874528, 854019, 28427, '<td valign="top">Not a very favourable pp for the man''s face.</td>', 'Not a very favourable pp for the man''s face.', '2010-02-20 17:40:00.000000', NULL, 1),
(5874529, 854167, 28427, '<td valign="top">I don''t know if this falls within the definition of "headwear".  Nevertheless a very beautiful photograph.</td>', 'I don''t know if this falls within the definition of "headwear".  Nevertheless a very beautiful photograph.', '2010-02-20 17:41:13.000000', NULL, 1),
(5874537, 853981, 110023, '<td valign="top">So artistic! Nice, clean, and crisp image. Perfect :)</td>', 'So artistic! Nice, clean, and crisp image. Perfect :)', '2010-02-20 17:52:49.000000', NULL, 1),
(5874538, 853888, 110023, '<td valign="top">Perfect capture of mood. Your editing is spot on for the subject! Adorable image. I really like this!</td>', 'Perfect capture of mood. Your editing is spot on for the subject! Adorable image. I really like this!', '2010-02-20 17:54:22.000000', NULL, 1),
(5874539, 853595, 110023, '<td valign="top">The colors are wonderful! Great editing on this image too. Love it!</td>', 'The colors are wonderful! Great editing on this image too. Love it!', '2010-02-20 17:55:07.000000', NULL, 1),
(5874540, 853573, 110023, '<td valign="top">This would be perfect on the wall of a vet''s office. Love the look on the dog''s face.  Great work!</td>', 'This would be perfect on the wall of a vet''s office. Love the look on the dog''s face.  Great work!', '2010-02-20 17:57:05.000000', NULL, 1),
(5874541, 854085, 110023, '<td valign="top">This is so candid and real! Love it. Great job on selecting a subject for this challenge. :)</td>', 'This is so candid and real! Love it. Great job on selecting a subject for this challenge. :)', '2010-02-20 17:59:41.000000', NULL, 1),
