(5874639, 853097, 88850, '<td valign="top">An extra point for the laugh!</td>', 'An extra point for the laugh!', '2010-02-20 21:18:34.000000', NULL, 1),
(5874642, 853907, 88850, '<td valign="top">Miss Molly wears her hat well!</td>', 'Miss Molly wears her hat well!', '2010-02-20 21:20:57.000000', NULL, 1),
