(5874731, 853992, 96572, '<td valign="top">I hope to see this as a blue! Amazing picture! Great focus! The eyes! The Model! Wow! Great Job!</td>', 'I hope to see this as a blue! Amazing picture! Great focus! The eyes! The Model! Wow! Great Job!', '2010-02-21 00:52:04.000000', NULL, 1),
(5874732, 853338, 83313, '<td valign="top">Nice shot. The title certainly makes the connection to the challenge, but without any headgear visible,... Well, you know.</td>', 'Nice shot. The title certainly makes the connection to the challenge, but without any headgear visible,... Well, you know.', '2010-02-21 00:55:07.000000', NULL, 1),
(5874734, 853166, 83313, '<td valign="top">Moooo!!!! (The universal language.)</td>', 'Moooo!!!! (The universal language.)', '2010-02-21 00:56:36.000000', NULL, 1),
(5874735, 853952, 83313, '<td valign="top">Reminds me of the <a href="//www.youtube.com/watch?v=KgV_IaZheDE&amp;feature=related" rel="nofollow" target="_blank">Coneheads</a> from Saturday Night Live. (What''s her skull shaped like?) Even the lighting seems like it would work for SNL.</td>', 'Reminds me of the Coneheads from Saturday Night Live. (What''s her skull shaped like?) Even the lighting seems like it would work for SNL.', '2010-02-21 01:04:37.000000', NULL, 1),
