INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5876127, 854113, 99506, '<td valign="top">You were robbed. This should have ribboned IMO</td>', 'You were robbed. This should have ribboned IMO', '2010-02-22 03:27:10.000000', NULL, 0),
